const listActionCalls = `-- name: ListActionCalls :many
SELECT id, workspace_id, action_id, action_version_id, connection_id, mode, side_effect, confirmation, approval, state, error_code, http_status, run_id, report_run_id, conversation_id, contact_id, message_id, tool_call_id, title, summary, input, bindings, request, response, result, decided_by_member_id, decision_reason, customer_message, cancel_reason, attempts, latency_ms, requested_at, confirmed_at, decided_at, sent_at, completed_at, expires_at, reported_at, created_at, updated_at FROM ai_action_calls
WHERE workspace_id = $1
    AND ($2::uuid IS NULL OR conversation_id = $2::uuid)
    AND ($3::uuid IS NULL OR action_id = $3::uuid)
    AND ($4::text IS NULL OR state = $4::text)
    AND ($5::uuid IS NULL OR id < $5::uuid)
ORDER BY id DESC
LIMIT $6
`

type ListActionCallsParams struct {
	WorkspaceID    ids.UUID  `json:"workspace_id"`
	ConversationID *ids.UUID `json:"conversation_id"`
	ActionID       *ids.UUID `json:"action_id"`
	State          *string   `json:"state"`
	BeforeID       *ids.UUID `json:"before_id"`
	RowLimit       int32     `json:"row_limit"`
}

// ListActionCalls returns the workspace's calls, newest first, filtered
// by conversation, action and state, starting after a cursor.
func (q *Queries) ListActionCalls(ctx context.Context, arg ListActionCallsParams) ([]AiActionCall, error) {
	rows, err := q.db.Query(ctx, listActionCalls,
		arg.WorkspaceID,
		arg.ConversationID,
		arg.ActionID,
		arg.State,
		arg.BeforeID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []AiActionCall
	for rows.Next() {
		var i AiActionCall
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.ActionID,
			&i.ActionVersionID,
			&i.ConnectionID,
			&i.Mode,
			&i.SideEffect,
			&i.Confirmation,
			&i.Approval,
			&i.State,
			&i.ErrorCode,
			&i.HttpStatus,
			&i.RunID,
			&i.ReportRunID,
			&i.ConversationID,
			&i.ContactID,
			&i.MessageID,
			&i.ToolCallID,
			&i.Title,
			&i.Summary,
			&i.Input,
			&i.Bindings,
			&i.Request,
			&i.Response,
			&i.Result,
			&i.DecidedByMemberID,
			&i.DecisionReason,
			&i.CustomerMessage,
			&i.CancelReason,
			&i.Attempts,
			&i.LatencyMs,
			&i.RequestedAt,
			&i.ConfirmedAt,
			&i.DecidedAt,
			&i.SentAt,
			&i.CompletedAt,
			&i.ExpiresAt,
			&i.ReportedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

